INSERT INTO feature VALUES('runs-beside-refusal','corpus','A source that runs while refused as total','corpus-expectations','implemented','ordinary',NULL,'An attribute block that states both runs("…") and refuses("…") settles only when both hold: the program runs to the stated value and the checker refuses it by the named refusal, so a loop with no inferable measure is witnessed running and refused as unbounded in one source.','surface-corpus surface-dispatcher','corpus/pathological/control/accessor-escape.gandr',NULL,NULL);
